
// 出了异常别白屏，把错打在底部那行小字上，看一眼就知道该修哪儿
window.onerror = function (m, u, l) {
  try {
    var h = document.getElementById('hint');
    if (h) h.textContent = 'ERR ' + m + ' @' + l;
  } catch (e) {}
  return false;
};
(function () {
  var FACES = ["data:image/png;base64,","data:image/png;base64,","data:image/png;base64,","data:image/png;base64,","data:image/png;base64,","data:image/png;base64,","data:image/png;base64,","data:image/png;base64,","data:image/png;base64,","data:image/png;base64,","data:image/png;base64,","data:image/png;base64,"];

  // 恐龙整套动作图：站、打招呼、走路、欢呼、盘腿坐
  var POSES = ["data:image/png;base64,","data:image/png;base64,","data:image/png;base64,","data:image/png;base64,","data:image/png;base64,"];
  var POSES_7 = [
    "data:image/png;base64,",
    "data:image/png;base64,",
    "data:image/png;base64,",
    "data:image/png;base64,",
    "data:image/png;base64,"
  ];
  var POSES_11 = [
    "data:image/png;base64,",
    "data:image/png;base64,",
    "data:image/png;base64,",
    "data:image/png;base64,",
    "data:image/png;base64,"
  ];
  // 和电脑端同一套规则：只在有整套动作的形象里按"今天是今年第几天"轮一个，
  // 电脑和手机同一天就是同一个形象，不会各演各的
  var POSE_KINDS = [6, 7, 11];
  var DAY_NO = Math.floor((Date.now() - new Date(new Date().getFullYear(), 0, 1).getTime()) / 86400000);
  var TODAY_SP = POSE_KINDS[DAY_NO % POSE_KINDS.length];
  if (TODAY_SP === 7) { POSES = POSES_7; }
  else if (TODAY_SP === 11) { POSES = POSES_11; }


  var CW = 260, CH = 200, CX = 130, CY = 124, TARGET_H = 152;
  var FY = [0.34, 0.44, 0.35, 0.35, 0.34, 0.28, 0.30, 0.30, 0.34, 0.40, 0.34, 0.37];
  var FW = [0.55, 0.62, 0.55, 0.62, 0.55, 0.60, 0.50, 0.55, 0.30, 0.45, 0.32, 0.72];

  var LINES = [
    "今天的课讲完了吗？歇一会儿吧。",
    "函数图像别画歪了啊。",
    "我在这儿呢，随时喊我。",
    "记得喝口水。",
    "这道题再想想，你会的。",
    "天冷了，多穿一件。",
    "改作业累了就抬头看看窗外。",
    "我是道，跟着你走到哪儿都行。",
    "别熬太晚，明天还有早自习。",
    "算错了不要紧，重来一遍就好。",
    "有事喊我一声，别自己扛着。",
    "桌上有杯水的话，先喝一口。"
  ];

  // 场景：手机上也铺整幅画，不再只是一块渐变底。图放在 assets 里，跟这个 html 同目录
  var SCENE_FILES = ['scene_city_s.png', 'scene_field_s.png', 'scene_sea_s.png',
                     'scene_flower_s.png', 'scene_xianxia_s.png', 'scene_home_s.png'];
  // 一天一张景，跟电脑端同步
  function todayScene() {
    var d = new Date();
    var doy = Math.floor((d - new Date(d.getFullYear(), 0, 0)) / 86400000);
    return doy % 6;
  }

  var scenes = [], sceneIdx = 0;
  SCENE_FILES.forEach(function (n, k) {
    var sim = new Image();
    sim.onload = function () { scenes[k] = sim; redraw(); };
    sim.src = n;
  });

  // 动作：跟电脑端共用一套编号 1 飞 2 御剑 3 坐骑 4 跳舞 5 喝茶 6 电视 7 滑板 8 轮滑
  var actKind = 0, actAmt = 0;
  // 走动：人往前走，场景往后退，看着就像真的在场景里走了一大段
  var walkX = 0, camX = 0, walkDir = 1;
  function actOfMode(m) {
    var map = { fly: 1, sword: 2, ride: 3, dance: 4, tea: 5, tv: 6, skate: 7, roller: 8 };
    return map[m] || 0;
  }
  function sceneForAct(k) {
    if (k === 1) return 2;                 // 披风飞 → 海边日落
    if (k === 2) return 4;                 // 御剑 → 仙侠云海
    if (k === 3) return 1;                 // 骑坐骑 → 乡野稻田
    if (k === 5) return 3;                 // 喝茶 → 花丛
    if (k === 6) return 5;                 // 看电视 → 客厅
    if (k === 7 || k === 8) return 0;      // 滑板、轮滑 → 城市夜景
    return -1;
  }

  var cv = document.getElementById('cv');
  var lockMood = 0;
  var hs = location.hash;
  if (hs === '#happy') lockMood = 1;
  else if (hs === '#angry') lockMood = 2;
  else if (hs === '#sad') lockMood = 3;
  var lockMode = (hs === '#sleep') ? 'sleep' : '';
  if (hs.indexOf('#act-') === 0) lockMode = hs.slice(5);   // 外部可以直接开局就御剑、飞、看电视
  var ctx = cv.getContext('2d');
  var bubble = document.getElementById('bubble');
  var scale = 1, dpr = 1;

  var imgs = [], species = 0, t = 0, lastT = 0, running = false, loadedCount = 0;
  var mode = 'idle', modeLeft = 4, mood = 0, moodLeft = 0, waveLeft = 0;
  var dx = 0, tilt = 0, hopY = 0, walkPhase = 0, lieAmt = 0;
  if (lockMode) { mode = lockMode; modeLeft = 99; if (lockMode === 'sleep') lieAmt = 1; }
  if (lockMode && actOfMode(lockMode)) {
    actKind = actOfMode(lockMode);
    actAmt = 1;
    sceneIdx = sceneForAct(actKind);
  }

  function resize() {
    dpr = window.devicePixelRatio || 1;
    var sw = document.getElementById('stage').clientWidth;
    var sh = document.getElementById('stage').clientHeight;
    scale = Math.min((sw * 0.94) / CW, (sh * 0.94) / CH);
    var cssW = CW * scale, cssH = CH * scale;
    cv.style.width = cssW + 'px';
    cv.style.height = cssH + 'px';
    cv.width = Math.round(cssW * dpr);
    cv.height = Math.round(cssH * dpr);
    ctx.setTransform(dpr * scale, 0, 0, dpr * scale, 0, 0);
    ctx.imageSmoothingEnabled = true;
    redraw();
  }

  function face(y, fr, kind) {
    if (fr < 3.5) return;
    var eyeDx = fr * 0.40, eyeY = y - fr * 0.05, lw = Math.max(1.1, fr * 0.055);
    var i;

    if (kind === 1) {
      ctx.fillStyle = 'rgba(255,138,152,0.17)';
      ctx.beginPath(); ctx.ellipse(0, y + fr * 0.09, fr * 0.52, fr * 0.43, 0, 0, 6.284); ctx.fill();
      ctx.fillStyle = 'rgba(255,146,160,0.38)';
      ctx.beginPath(); ctx.ellipse(-eyeDx, y + fr * 0.31, fr * 0.21, fr * 0.13, 0, 0, 6.284); ctx.fill();
      ctx.beginPath(); ctx.ellipse(eyeDx, y + fr * 0.31, fr * 0.21, fr * 0.13, 0, 0, 6.284); ctx.fill();
      if (fr > 14) {
        ctx.strokeStyle = 'rgba(224,92,112,0.65)';
        ctx.lineWidth = lw; ctx.lineCap = 'round';
        ctx.beginPath();
        ctx.ellipse(0, y + fr * 0.40, fr * 0.14, fr * 0.12, 0, 22 * Math.PI / 180, 158 * Math.PI / 180);
        ctx.stroke();
      }
    } else if (kind === 2) {
      ctx.fillStyle = 'rgba(246,96,96,0.16)';
      ctx.beginPath(); ctx.ellipse(0, y + fr * 0.09, fr * 0.52, fr * 0.43, 0, 0, 6.284); ctx.fill();
      ctx.fillStyle = 'rgba(238,96,96,0.29)';
      ctx.beginPath(); ctx.ellipse(-eyeDx, y + fr * 0.31, fr * 0.21, fr * 0.13, 0, 0, 6.284); ctx.fill();
      ctx.beginPath(); ctx.ellipse(eyeDx, y + fr * 0.31, fr * 0.21, fr * 0.13, 0, 0, 6.284); ctx.fill();
      var ax = fr * 0.98, ay = y - fr * 0.62, s4 = fr * 0.10;
      ctx.strokeStyle = 'rgba(222,72,72,0.92)';
      ctx.lineWidth = lw * 1.05; ctx.lineCap = 'round';
      ctx.beginPath();
      ctx.moveTo(ax - s4 * 1.4, ay - s4 * 0.35); ctx.lineTo(ax - s4 * 0.35, ay - s4 * 1.4);
      ctx.moveTo(ax + s4 * 0.35, ay + s4 * 1.4); ctx.lineTo(ax + s4 * 1.4, ay + s4 * 0.35);
      ctx.moveTo(ax - s4 * 1.4, ay + s4 * 0.35); ctx.lineTo(ax - s4 * 0.35, ay + s4 * 1.4);
      ctx.moveTo(ax + s4 * 0.35, ay - s4 * 1.4); ctx.lineTo(ax + s4 * 1.4, ay - s4 * 0.35);
      ctx.stroke();
    } else if (kind === 3) {
      ctx.fillStyle = 'rgba(126,176,226,0.28)';
      ctx.beginPath(); ctx.ellipse(-eyeDx, y - fr * 0.01, fr * 0.20, fr * 0.15, 0, 0, 6.284); ctx.fill();
      ctx.beginPath(); ctx.ellipse(eyeDx, y - fr * 0.01, fr * 0.20, fr * 0.15, 0, 0, 6.284); ctx.fill();
      tear(-eyeDx, eyeY + fr * 0.20, fr * 0.17);
      tear(eyeDx * 0.82, eyeY + fr * 0.36, fr * 0.13);
    } else if (kind === 4) {
      ctx.strokeStyle = 'rgba(118,128,150,0.76)';
      ctx.lineWidth = lw; ctx.lineCap = 'round';
      ctx.beginPath();
      ctx.moveTo(fr * 0.52, y - fr * 0.62); ctx.lineTo(fr * 0.60, y - fr * 0.34);
      ctx.moveTo(fr * 0.70, y - fr * 0.58); ctx.lineTo(fr * 0.76, y - fr * 0.30);
      ctx.stroke();
      ctx.strokeStyle = 'rgba(208,120,60,0.67)';
      ctx.beginPath(); ctx.ellipse(0, y + fr * 0.36, fr * 0.10, fr * 0.10, 0, 0, 6.284); ctx.stroke();
    } else if (kind === 5 || kind === 6) {
      // 光画眼皮弧没用，原图的黑眼珠还在底下，得先拿脸上的一块肤色把它盖掉
      var skim = imgs[species];
      if (skim && skim.naturalWidth) {
        var sxp = skim.naturalWidth * 0.36;
        var syp2 = skim.naturalHeight * ((FY[species] || 0.36) + 0.20);
        var sww = skim.naturalWidth * 0.28;
        var shh = skim.naturalHeight * 0.075;
        ctx.save();
        ctx.beginPath();
        ctx.ellipse(0, eyeY, eyeDx + fr * 0.52, fr * 0.46, 0, 0, 6.284);
        ctx.clip();
        ctx.drawImage(skim, sxp, syp2, sww, shh,
                      -eyeDx - fr * 0.62, eyeY - fr * 0.5, eyeDx * 2 + fr * 1.24, fr);
        ctx.restore();
      }
      ctx.strokeStyle = 'rgba(66,70,84,0.92)';
      ctx.lineWidth = lw; ctx.lineCap = 'round';
      ctx.beginPath();
      ctx.ellipse(-eyeDx, eyeY + fr * 0.02, fr * 0.17, fr * 0.11, 0, 20 * Math.PI / 180, 160 * Math.PI / 180);
      ctx.stroke();
      ctx.beginPath();
      ctx.ellipse(eyeDx, eyeY + fr * 0.02, fr * 0.17, fr * 0.11, 0, 20 * Math.PI / 180, 160 * Math.PI / 180);
      ctx.stroke();
      ctx.strokeStyle = 'rgba(150,116,120,0.57)';
      ctx.lineWidth = lw * 0.9;
      ctx.beginPath(); ctx.ellipse(0, y + fr * 0.32, fr * 0.09, fr * 0.08, 0, 0, 6.284); ctx.stroke();
    }
  }

  function tear(x, y, r) {
    if (r < 1.2) return;
    ctx.fillStyle = 'rgba(108,172,236,0.85)';
    ctx.beginPath(); ctx.ellipse(x, y + r * 0.625, r * 0.50, r * 0.625, 0, 0, 6.284); ctx.fill();
    ctx.beginPath();
    ctx.moveTo(x, y - r * 1.05);
    ctx.lineTo(x - r * 0.42, y + r * 0.30);
    ctx.lineTo(x + r * 0.42, y + r * 0.30);
    ctx.closePath(); ctx.fill();
    ctx.fillStyle = 'rgba(255,255,255,0.60)';
    ctx.beginPath(); ctx.ellipse(x, y + r * 0.35, r * 0.15, r * 0.17, 0, 0, 6.284); ctx.fill();
  }

  // 铺场景：整屏用 CSS 背景铺，人画在上面那层透明画布上
  var bgEl = document.getElementById('bg');
  // 场景先停用：画面就是纯底色，只剩形象。代码都留着，以后优化好了把这里改回 true
  var SCENE_ON = false;

  function drawScene() {
    if (!SCENE_ON) {
      if (bgEl && bgEl.classList.contains('show')) bgEl.classList.remove('show');
      return;
    }
    if (!bgEl) return;
    if (sceneIdx < 0 || !scenes[sceneIdx] || !scenes[sceneIdx].naturalWidth) {
      if (bgEl.classList.contains('show')) bgEl.classList.remove('show');
      return;
    }
    var url = 'url("' + SCENE_FILES[sceneIdx] + '")';
    if (bgEl.style.backgroundImage !== url) bgEl.style.backgroundImage = url;
    // 走的时候镜头跟着滚，人不用离开画面中心，场景自己退
    bgEl.style.backgroundPosition = 'calc(50% + ' + Math.round(camX) + 'px) center';
    bgEl.classList.add('show');
  }

  // 场景里自己会动的东西：雨、萤火、浪、花瓣、云、灯
  function drawSceneLife() {
    if (!SCENE_ON) return;
    var i, x, y, a;
    if (sceneIdx === 0) {
      ctx.strokeStyle = 'rgba(210,230,255,0.35)';
      ctx.lineWidth = 1;
      for (i = 0; i < 14; i++) {
        x = (i * 37 + t * 26) % CW;
        y = (i * 23 + t * 78) % CH;
        ctx.beginPath(); ctx.moveTo(x, y); ctx.lineTo(x - 3, y + 9); ctx.stroke();
      }
      // 街上有人路过，从右往左，远的浅近的深
      for (i = 0; i < 3; i++) {
        var psx = CW + 14 - ((t * (16 + i * 7) + i * 90) % (CW + 28));
        var psy = CH * 0.66 + i * CH * 0.07;
        var phh = 13 + i * 4;
        ctx.fillStyle = 'rgba(20,26,44,' + (0.42 + i * 0.18) + ')';
        ctx.beginPath(); ctx.arc(psx, psy - phh, phh * 0.22, 0, 6.284); ctx.fill();
        ctx.fillRect(psx - phh * 0.13, psy - phh * 0.80, phh * 0.26, phh * 0.80);
      }
    } else if (sceneIdx === 1) {
      for (i = 0; i < 12; i++) {
        x = (i * 41 + Math.sin(t * 0.9 + i) * 10) % CW; if (x < 0) x += CW;
        y = 40 + (i * 29) % 100 + Math.sin(t * 1.6 + i * 2) * 8;
        a = 0.25 + 0.35 * (0.5 + 0.5 * Math.sin(t * 2.4 + i));
        ctx.fillStyle = 'rgba(255,240,150,' + a + ')';
        ctx.beginPath(); ctx.arc(x, y, 1.6, 0, 6.284); ctx.fill();
      }
      // 风从稻田上刮过：亮带一浪一浪往右推，稻叶被吹歪
      ctx.strokeStyle = 'rgba(255,255,214,0.22)';
      ctx.lineWidth = 2;
      for (i = 0; i < 4; i++) {
        var wx = ((t * 22 + i * 70) % (CW + 60)) - 30;
        var wy = CH * 0.52 + i * CH * 0.06 + Math.sin(t * 1.1 + i) * 3;
        ctx.beginPath(); ctx.moveTo(wx, wy); ctx.lineTo(wx + 34, wy - 3); ctx.stroke();
      }
      ctx.strokeStyle = 'rgba(214,240,152,0.42)';
      ctx.lineWidth = 1;
      for (i = 0; i < 10; i++) {
        var bx0 = (i * 26 + 8) % CW;
        var by0 = CH * 0.54 + (i % 4) * 14;
        ctx.beginPath(); ctx.moveTo(bx0, by0 + 8);
        ctx.lineTo(bx0 + Math.sin(t * 1.7 + i) * 4, by0);
        ctx.stroke();
      }
    } else if (sceneIdx === 2) {
      ctx.strokeStyle = 'rgba(255,255,255,0.5)';
      ctx.lineWidth = 1.6;
      for (i = 0; i < 4; i++) {
        y = 62 + i * 18;
        x = Math.sin(t * 0.8 + i) * 12;
        ctx.beginPath();
        ctx.moveTo(-10 + x, y);
        ctx.bezierCurveTo(60 + x, y - 5, 140 + x, y + 5, CW + 10 + x, y - 2);
        ctx.stroke();
      }
    } else if (sceneIdx === 3) {
      for (i = 0; i < 12; i++) {
        x = (i * 47 + Math.sin(t * 0.7 + i) * 18) % CW;
        y = (i * 53 + t * 34) % CH;
        ctx.fillStyle = (i % 3 === 0) ? 'rgba(255,232,150,0.7)' : 'rgba(255,190,215,0.7)';
        ctx.beginPath(); ctx.ellipse(x, y, 2.2, 1.4, t * 0.6 + i, 0, 6.284); ctx.fill();
      }
      // 两只蝴蝶在草上绕圈，翅膀一开一合
      for (i = 0; i < 2; i++) {
        var bph = t * 0.8 + i * 2.3;
        var bxx = CW * 0.5 + Math.sin(bph * 1.15) * 62;
        var byy = CH * 0.42 + i * 26 + Math.sin(bph * 1.9) * 14;
        var flap = 2.0 + 2.2 * Math.abs(Math.sin(t * 9.4 + i * 1.5));
        ctx.fillStyle = (i === 0) ? 'rgba(255,208,116,0.8)' : 'rgba(252,250,246,0.8)';
        ctx.beginPath(); ctx.ellipse(bxx - flap * 0.5, byy, flap, 2.4, 0, 0, 6.284); ctx.fill();
        ctx.beginPath(); ctx.ellipse(bxx + flap * 0.5, byy, flap, 2.4, 0, 0, 6.284); ctx.fill();
        ctx.fillStyle = 'rgba(90,70,50,0.8)';
        ctx.beginPath(); ctx.ellipse(bxx, byy, 1.1, 2.2, 0, 0, 6.284); ctx.fill();
      }
    } else if (sceneIdx === 4) {
      ctx.fillStyle = 'rgba(255,255,255,0.16)';
      for (i = 0; i < 2; i++) {
        x = (t * 8 + i * 120) % (CW + 80) - 40;
        ctx.beginPath(); ctx.ellipse(x, 46 + i * 16, 46, 13, 0, 0, 6.284); ctx.fill();
      }
      for (i = 0; i < 10; i++) {
        x = (i * 31 + Math.sin(t * 0.8 + i) * 14) % CW;
        y = (i * 41 + t * 26) % CH;
        ctx.fillStyle = 'rgba(255,196,224,0.75)';
        ctx.beginPath(); ctx.ellipse(x, y, 2, 1.2, i + t * 0.5, 0, 6.284); ctx.fill();
      }
    } else if (sceneIdx === 5) {
      var br = 0.5 + 0.5 * Math.sin(t * 2.0);
      ctx.fillStyle = 'rgba(255,214,140,' + (0.10 + 0.08 * br) + ')';
      ctx.beginPath(); ctx.ellipse(38, 130, 34, 40, 0, 0, 6.284); ctx.fill();
      // 客厅那台电视一直开着，屏幕上一道光在扫
      var tvx = CW * 0.78, tvy = CH * 0.40, tvw = CW * 0.20, tvh = CH * 0.13;
      ctx.fillStyle = 'rgba(126,186,255,' + (0.55 + 0.25 * br) + ')';
      ctx.fillRect(tvx, tvy, tvw, tvh);
      ctx.fillStyle = 'rgba(255,255,255,0.7)';
      ctx.fillRect(tvx + 2, tvy + tvh * ((t * 0.9) % 1), tvw - 4, 1.6);
    }
  }

  // 动作道具：front=false 画在身后（披风、剑、坐骑），true 画在身前（杯子、板、音符）
  function drawActProps(front) {
    if (actAmt < 0.03 || actKind <= 0) return;
    var a = actAmt, i, x, y;
    if (!front) {
      if (actKind === 1) {
        // 披风：从肩上往后甩的一块红布，下摆带三个波浪
        ctx.fillStyle = 'rgba(198,58,48,' + 0.9 * a + ')';
        ctx.beginPath();
        ctx.moveTo(-6, -TARGET_H * 0.60);
        ctx.quadraticCurveTo(-TARGET_H * 0.52, -TARGET_H * 0.56, -TARGET_H * 0.60, -TARGET_H * 0.18);
        ctx.quadraticCurveTo(-TARGET_H * 0.30, -TARGET_H * 0.06, -TARGET_H * 0.06, -TARGET_H * 0.22);
        ctx.quadraticCurveTo(2, -TARGET_H * 0.42, -6, -TARGET_H * 0.60);
        ctx.closePath(); ctx.fill();
        ctx.strokeStyle = 'rgba(226,182,96,' + 0.85 * a + ')';
        ctx.lineWidth = 1.5;
        ctx.beginPath();
        ctx.moveTo(-TARGET_H * 0.60, -TARGET_H * 0.18);
        ctx.quadraticCurveTo(-TARGET_H * 0.30, -TARGET_H * 0.06, -TARGET_H * 0.06, -TARGET_H * 0.22);
        ctx.stroke();
      } else if (actKind === 2) {
        // 御剑：脚下一道长光
        ctx.fillStyle = 'rgba(150,220,255,' + 0.7 * a + ')';
        ctx.beginPath(); ctx.ellipse(0, 5, TARGET_H * 0.46, 5, 0, 0, 6.284); ctx.fill();
        ctx.fillStyle = 'rgba(255,255,255,' + 0.55 * a + ')';
        ctx.beginPath(); ctx.ellipse(0, 4, TARGET_H * 0.30, 2.2, 0, 0, 6.284); ctx.fill();
      } else if (actKind === 3) {
        // 坐骑：一只侧身的小兽，一头一尾
        ctx.fillStyle = 'rgba(122,96,70,' + 0.92 * a + ')';
        ctx.beginPath(); ctx.ellipse(0, -8, TARGET_H * 0.48, TARGET_H * 0.16, 0, 0, 6.284); ctx.fill();
        ctx.beginPath(); ctx.arc(-TARGET_H * 0.44, -TARGET_H * 0.22, TARGET_H * 0.10, 0, 6.284); ctx.fill();
        ctx.fillStyle = 'rgba(92,72,54,' + 0.9 * a + ')';
        ctx.beginPath(); ctx.moveTo(TARGET_H * 0.46, -TARGET_H * 0.14);
        ctx.quadraticCurveTo(TARGET_H * 0.58, -TARGET_H * 0.24, TARGET_H * 0.52, -TARGET_H * 0.04);
        ctx.fill();
      }
    } else {
      if (actKind === 5) {
        // 喝茶：手里一只杯子，杯口有一点热气的亮
        x = 12; y = -TARGET_H * 0.40;
        ctx.fillStyle = 'rgba(250,250,248,' + a + ')';
        ctx.beginPath(); ctx.rect(x - 6, y - 8, 12, 15); ctx.fill();
        ctx.strokeStyle = 'rgba(205,200,192,' + a + ')'; ctx.lineWidth = 1.3;
        ctx.beginPath(); ctx.rect(x - 6, y - 8, 12, 15); ctx.stroke();
        ctx.fillStyle = 'rgba(116,70,42,' + a + ')';
        ctx.beginPath(); ctx.ellipse(x, y - 7, 5, 1.6, 0, 0, 6.284); ctx.fill();
      } else if (actKind === 7 || actKind === 8) {
        // 滑板、轮滑：脚下一条板
        ctx.fillStyle = 'rgba(58,58,68,' + a + ')';
        ctx.beginPath(); ctx.ellipse(0, 3, TARGET_H * 0.26, 3.4, 0, 0, 6.284); ctx.fill();
      } else if (actKind === 4) {
        // 跳舞：三个往上飘的音符
        for (i = 0; i < 3; i++) {
          ctx.fillStyle = 'rgba(255,225,140,' + 0.7 * a + ')';
          x = Math.sin(t * 2 + i * 2) * 22;
          y = -TARGET_H * 0.86 - (t * 26 + i * 24) % 60;
          ctx.beginPath(); ctx.arc(x, y, 3, 0, 6.284); ctx.fill();
        }
      }
    }
  }

  function redraw() {
    ctx.clearRect(0, 0, CW, CH);
    drawScene();
    if (sceneIdx >= 0) drawSceneLife();
    var img = imgs[species];
    if (!img || !img.complete || !img.naturalWidth) return;

    var ratio = img.naturalWidth / img.naturalHeight;
    var baseW = TARGET_H * ratio;
    var footY = CY + 68;

    var br = Math.sin(t * 2.2);
    var sx = 1 - 0.014 * br, sy = 1 + 0.018 * br;
    var bob = -Math.abs(br) * 2.0;
    // 手机是竖着的画布，人横过来根本放不下，所以这里是趴着睡：压矮、变宽、往床上沉
    if (lieAmt > 0.02) {
      sy *= 1 - 0.30 * lieAmt;
      sx *= 1 + 0.12 * lieAmt;
      bob = bob * (1 - lieAmt) + 20 * lieAmt;
    }

    var bedA = lieAmt > 0.45 ? (lieAmt - 0.45) / 0.55 : 0;
    if (bedA > 0) bedA = Math.min(1, bedA);

    ctx.save();
    ctx.translate(CX + dx + walkX, footY + hopY + bob);
    ctx.rotate(tilt * Math.PI / 180);
    ctx.scale(sx, sy);
    drawActProps(false);

    // 床：床身、床沿高光、床头板、枕头。都在角色本地坐标里画，跟着一起躺
    if (bedA > 0) {
      var ba = 238 * bedA;
      var bx0 = -baseW * 0.56, bx1 = baseW * 0.56;
      var by0 = -TARGET_H - 12, by1 = 12;
      ctx.fillStyle = 'rgba(206,182,152,' + (ba / 255) + ')';
      ctx.beginPath();
      ctx.rect(bx0, by0, bx1 - bx0, by1 - by0);
      ctx.fill();
      // 床沿一道高光，让床身有厚度，别像一块平地
      ctx.strokeStyle = 'rgba(236,220,198,' + (ba / 255) + ')';
      ctx.lineWidth = 3;
      ctx.beginPath();
      ctx.moveTo(bx0, by1 - 14); ctx.lineTo(bx1, by1 - 14);
      ctx.stroke();
      // 床头板
      ctx.fillStyle = 'rgba(138,102,70,' + (ba / 255) + ')';
      ctx.beginPath();
      ctx.rect(bx0, by0, bx1 - bx0, 18);
      ctx.fill();
      // 枕头
      ctx.fillStyle = 'rgba(252,250,244,' + (ba / 255) + ')';
      ctx.beginPath();
      ctx.ellipse(bx0 + (bx1 - bx0) * 0.22, -TARGET_H + 0.215 * TARGET_H,
                  (bx1 - bx0) * 0.44 / 2, TARGET_H * 0.19 / 2, 0, 0, 6.284);
      ctx.fill();
    }

    // 恐龙有整套动作图：不走切条变形那套，直接按它当下在干嘛换图
    var poseP = -1;
    var curPose = poseImgsBySp[species];
    if (curPose && curPose.length >= 5 && lieAmt < 0.40) {
      if (waveLeft > 0) poseP = 1;
      else if (mode === 'walk' || mode === 'run') poseP = 2;
      else if (actKind >= 4 && actKind <= 5) poseP = 3;
      else if (actKind === 6) poseP = 4;
      else poseP = 0;
    }
    if (poseP >= 0 && curPose && curPose[poseP] && curPose[poseP].complete && curPose[poseP].naturalWidth) {
      var pim2 = curPose[poseP];
      var pwid = TARGET_H * (pim2.naturalWidth / pim2.naturalHeight);
      ctx.drawImage(pim2, -pwid / 2, -TARGET_H, pwid, TARGET_H);
      ctx.restore();
      return;
    }

    var strips = 26, stripH = TARGET_H / strips;
    var imgScale = img.naturalHeight / TARGET_H;
    var amp = (mode === 'run') ? 4.4 : ((mode === 'walk') ? 2.6 : 0.9);
    var ph0 = t * ((mode === 'run') ? 11.0 : 7.2);
    var i, off, fy, yy, sh, syp, shp;
    for (i = 0; i < strips; i++) {
      fy = (i + 0.5) / strips;
      off = amp * Math.pow(fy, 1.7) * Math.sin(ph0 - fy * 3.2);
      if (waveLeft > 0 && fy < 0.68) off += 12 * (0.68 - fy) * Math.sin(t * 13);
      yy = -TARGET_H + i * stripH;
      sh = stripH + 1.1;
      syp = i * stripH * imgScale;
      shp = Math.min(img.naturalHeight - syp, sh * imgScale);
      if (shp <= 0.5) continue;
      ctx.drawImage(img, 0, syp, img.naturalWidth, shp, -baseW / 2 + off, yy, baseW, sh);
    }

    var fyp = FY[species] || 0.36, fwp = FW[species] || 0.55;
    var fOff = amp * Math.pow(fyp, 1.7) * Math.sin(ph0 - fyp * 3.2);
    if (waveLeft > 0 && fyp < 0.68) fOff += 12 * (0.68 - fyp) * Math.sin(t * 13);
    var kind = 0;
    if (mode === 'sleep') kind = 6; else if (mood > 0) kind = mood;
    ctx.save();
    ctx.translate(fOff, 0);
    face(-TARGET_H + fyp * TARGET_H, baseW * fwp / 2, kind);
    ctx.restore();

    // 被子：浅蓝圆角，被头压在脖子以下，不糊住脸。近不透明，免得透出底色发脏
    if (bedA > 0) {
      var qa = (186 + 34 * bedA) / 255;
      var qy0 = -TARGET_H + (fyp + 0.125) * TARGET_H;
      if (qy0 > -TARGET_H * 0.16) qy0 = -TARGET_H * 0.16;
      var qy1 = 8;
      var qx0 = -baseW * 0.33, qx1 = baseW * 0.33;
      var qw = qx1 - qx0, qh = qy1 - qy0;
      var qr = Math.min(qw * 0.16, 9);
      if (qr < 2.5) qr = 2.5;
      var grd = ctx.createLinearGradient(0, qy0, 0, qy1);
      grd.addColorStop(0, 'rgba(' + Math.min(255, 186 + 34 * bedA + 20) + ',182,204,' + qa + ')');
      grd.addColorStop(1, 'rgba(88,118,178,' + qa + ')');
      ctx.fillStyle = grd;
      ctx.beginPath();
      // 手动画圆角，别用 roundRect，老一点的浏览器不一定有
      ctx.moveTo(qx0 + qr, qy0);
      ctx.lineTo(qx1 - qr, qy0);
      ctx.arcTo(qx1, qy0, qx1, qy0 + qr, qr);
      ctx.lineTo(qx1, qy1 - qr);
      ctx.arcTo(qx1, qy1, qx1 - qr, qy1, qr);
      ctx.lineTo(qx0 + qr, qy1);
      ctx.arcTo(qx0, qy1, qx0, qy1 - qr, qr);
      ctx.lineTo(qx0, qy0 + qr);
      ctx.arcTo(qx0, qy0, qx0 + qr, qy0, qr);
      ctx.closePath();
      ctx.fill();
      // 被头一道亮边
      ctx.strokeStyle = 'rgba(232,240,252,' + qa + ')';
      ctx.lineWidth = 3;
      ctx.beginPath();
      ctx.moveTo(qx0 + qr, qy0 + 1.5); ctx.lineTo(qx1 - qr, qy0 + 1.5);
      ctx.stroke();
      // 两道褶，被子才不像一块板
      ctx.strokeStyle = 'rgba(118,146,200,' + qa + ')';
      ctx.lineWidth = 1.3;
      for (var qi = 0; qi < 2; qi++) {
        var qx = qx0 + qw * (0.30 + qi * 0.36) + Math.sin(t * 1.9 + qi) * 1.6;
        ctx.beginPath();
        ctx.moveTo(qx, qy0 + 6);
        ctx.lineTo(qx + Math.sin(t * 1.2 + qi) * 1.2, qy1 - 2);
        ctx.stroke();
      }
    }

    drawActProps(true);
    ctx.restore();
  }

  function tick(now) {
    if (!lastT) lastT = now;
    var dt = Math.min(0.05, (now - lastT) / 1000);
    lastT = now;
    t += dt;
    if (lockMood) { mood = lockMood; moodLeft = 99; }

    modeLeft -= dt;
    if (moodLeft > 0) { moodLeft -= dt; if (moodLeft <= 0) mood = 0; }
    if (waveLeft > 0) { waveLeft -= dt; if (waveLeft <= 0 && mode === 'wave') mode = 'idle'; }

    if (mode === 'walk') {
      walkPhase += dt;
      dx = Math.sin(walkPhase * 1.6) * 16;
    } else if (mode === 'run') {
      walkPhase += dt * 1.9;
      dx = Math.sin(walkPhase * 1.6) * 26;
      tilt = walkPhase % 3.14 < 1.57 ? 12 : -12;
    } else if (mode === 'wave') {
      tilt = Math.sin(t * 9) * 3.2;
      dx = 0;
    } else if (mode === 'sleep') {
      dx = 0; tilt = -2.5;
    } else {
      dx *= 0.9; tilt *= 0.9;
    }

    // 躺下的程度平滑过渡，别一下子翻过去
    lieAmt += ((mode === 'sleep') ? 1 : -1) * dt * 2.6;
    if (lieAmt < 0) lieAmt = 0;
    if (lieAmt > 1) lieAmt = 1;

    hopY = 0;
    if (mode === 'hop') {
      hopY = -Math.abs(Math.sin(t * 6.2)) * 22;
    }

    // 走动：人往前走，场景往后退；走到画面边上了就转身往回走
    if (mode === 'walk' || mode === 'run') {
      var sp = (mode === 'run') ? 52 : 26;
      walkX += walkDir * sp * dt;
      camX -= walkDir * sp * dt * 2.4;
      if (walkX > 52) { walkX = 52; walkDir = -1; }
      if (walkX < -52) { walkX = -52; walkDir = 1; }
      if (camX > 420) camX = 420;
      if (camX < -420) camX = -420;
    } else {
      walkX *= 0.88;
      camX *= 0.94;
    }

    // 动作的进出：先把 actKind 定下来，再用 actAmt 淡入淡出，切换时不会一下蹦出来
    var wantAct = actOfMode(mode);
    if (wantAct) actKind = wantAct;
    actAmt += ((wantAct ? 1 : 0) - actAmt) * Math.min(1, dt * 5);
    if (actAmt < 0.03 && !wantAct) { actAmt = 0; actKind = 0; }
    // 场景常驻：平时就在今天那张景里待着，做动作时换到更配的景里去
    var wantScene = sceneForAct(actKind);
    if (actAmt > 0.12 && wantScene >= 0) sceneIdx = wantScene;
    else if (actKind === 0) sceneIdx = todayScene();

    // 飞、御剑、骑坐骑这几个是离地的，得抬起来再轻轻飘
    if (mode === 'fly' || mode === 'sword' || mode === 'ride') {
      hopY -= 16 * actAmt;
      tilt = Math.sin(t * 1.4) * 4.5 * actAmt;
    }

    if (modeLeft <= 0) {
      mode = pickMode();
      modeLeft = 6 + Math.random() * 8;
      if (mode === 'walk') walkPhase = 0;
      if (mode === 'hop') modeLeft = 1.6;
    }

    if (moodLeft <= 0 && Math.random() < 0.02) {
      mood = [1, 2, 3, 4, 2, 1][Math.floor(Math.random() * 6)];
      moodLeft = 2.4;
    }

    redraw();
    requestAnimationFrame(tick);
  }

  function pickMode() {
    if (lockMode) return lockMode;
    var r = Math.random();
    // 带动作的先来：飞、御剑、骑坐骑、喝茶、看电视、滑板，各占一点
    if (r < 0.07) return 'fly';
    if (r < 0.13) return 'sword';
    if (r < 0.19) return 'ride';
    if (r < 0.25) return 'tea';
    if (r < 0.31) return 'tv';
    if (r < 0.37) return 'skate';
    if (r < 0.42) return 'dance';
    if (r < 0.58) return 'idle';
    if (r < 0.72) return 'walk';
    if (r < 0.82) return 'run';
    if (r < 0.92) return 'wave';
    return 'hop';
  }

  var sayTimer = null;
  function say(text) {
    bubble.textContent = text;
    bubble.classList.add('show');
    if (sayTimer) clearTimeout(sayTimer);
    sayTimer = setTimeout(function () { bubble.classList.remove('show'); }, 3200);
  }

  function poke() {
    waveLeft = 1.8;
    mode = 'wave';
    tilt = Math.sin(t * 9) * 3.2;
    mood = 1; moodLeft = 2.2;
    say(allLines()[Math.floor(Math.random() * allLines().length)]);
  }

  cv.addEventListener('pointerdown', function (e) { e.preventDefault(); poke(); });

  document.getElementById('btnTalk').addEventListener('click', function () {
    askMode = 'chat';
    try { askInput.placeholder = '跟道说句话……'; } catch (e) {}
    openAsk();
  });

  document.getElementById('btnMood').addEventListener('click', function () {
    mood = [1, 2, 3, 4][Math.floor(Math.random() * 4)];
    moodLeft = 3.0;
  });

  // 换个动作：挨个挑一个带场景的，切完立刻说一句它自己在干什么
  var ACT_NAMES = ['fly', 'sword', 'ride', 'tea', 'tv', 'skate', 'dance'];
  var ACT_WORDS = {
    fly: '披上披风，飞一段。', sword: '踩剑上，御风走。', ride: '上来，带你跑一程。',
    tea: '喝口热的，慢慢来。', tv: '我坐会儿电视。', skate: '踩上板，溜一段。', dance: '给我来点节拍。'
  };
  document.getElementById('btnAct').addEventListener('click', function () {
    var m = ACT_NAMES[Math.floor(Math.random() * ACT_NAMES.length)];
    mode = m; modeLeft = 5 + Math.random() * 4;
    actKind = actOfMode(m); actAmt = 1;
    sceneIdx = sceneForAct(actKind);
    say(ACT_WORDS[m]);
  });

  document.getElementById('btnSwap').addEventListener('click', function () {
    var _ks = [6, 7, 11];
    var _ci = _ks.indexOf(species);
    species = _ks[(_ci + 1 + Math.floor(Math.random() * (_ks.length - 1))) % _ks.length];
    mood = 1; moodLeft = 2.0;
    dx = 0;
  });

  window.addEventListener('resize', resize);
  window.addEventListener('orientationchange', function () { setTimeout(resize, 200); });

  var total = FACES.length;
  FACES.forEach(function (src, idx) {
    var img = new Image();
    img.onload = function () {
      imgs[idx] = img;
      loadedCount++;
      if (loadedCount === total) {
        // 手机上也是一天换一个模样，跟电脑端对上
        var _d = new Date();
        // 和电脑端完全同一套规则：只在 6 / 7 / 11 这三个有整套动作的形象里轮，
        // 同一天两端是同一个形象
        var _kinds = [6, 7, 11];
        species = _kinds[Math.floor((_d - new Date(_d.getFullYear(), 0, 0)) / 86400000) % _kinds.length];
        resize(); if (!running) { running = true; requestAnimationFrame(tick); }
      }
    };
    img.src = src;
    imgs[idx] = img;
  });

  // 动作图也预加载：先到先用，画的时候只认已经加载完的那张
  var poseImgs = [];
  // 三套姿势图分开预加载：恐龙用 POSES，黑发少年用 POSES_7，银发剑客用 POSES_11。
  // 以前这里只加载了 POSES 一套，POSES_7 / POSES_11 算出来也没人用，等于白算
  var POSE_SETS = { 4: POSES, 7: POSES_7, 11: POSES_11 };
  var poseImgsBySp = {};
  (function () {
    Object.keys(POSE_SETS).forEach(function (k) {
      var arr = [];
      var list = POSE_SETS[k];
      for (var _pi = 0; _pi < list.length; _pi++) {
        var _pim = new Image();
        _pim.src = list[_pi];
        arr.push(_pim);
      }
      poseImgsBySp[k] = arr;
      if (k === '4') poseImgs = arr;
    });
  })();

  /* ========== 大脑 & 自我更新 ========== */
  var extraLines = [];
  var waitingIds = {};
  var seq = 0;
  var askBox = document.getElementById('ask');
  var askInput = document.getElementById('askInput');

  function allLines() { return LINES.concat(extraLines); }

  function loadExtras() {
    if (!window.DaoNative) return;
    try {
      var a = JSON.parse(DaoNative.getLines());
      if (a && a.length) extraLines = a;
    } catch (e) {}
  }

  var askMode = 'chat';

  function askSide(md) {
    askMode = md;
    try {
      askInput.placeholder = (md === 'explain') ? '把题目贴进来，我给你讲思路' : '跟道说句话……';
    } catch (e) {}
    openAsk();
  }

  function openAsk() {
    if (!askBox) return;
    askBox.classList.add('show');
    try { askInput.value = ''; askInput.focus(); } catch (e) {}
  }

  function closeAsk() { if (askBox) askBox.classList.remove('show'); }

  function setMoodByCode(m) {
    if (!m) { mood = 0; moodLeft = 0; return; }
    mood = (m === 7 || m === 8) ? (m === 8 ? 1 : 4) : m;
    moodLeft = 3.4;
  }

  function askBrain(text, md) {
    if (!window.DaoNative) { say('我这会儿没有大脑，得回电脑上才行。'); return; }
    md = md || 'chat';
    var id = 'q' + (++seq);
    waitingIds[id] = 1;
    bubble.classList.add('show');
    bubble.textContent = (md === 'explain') ? '我看看这题……' : '……';
    waveLeft = 1.8; mode = 'wave';
    if (md === 'explain' && window.DaoNative.explain) DaoNative.explain(text, id);
    else DaoNative.chat(text, id);
  }

  window.__daoReply = function (id, reply, m) {
    if (!waitingIds[id]) return;
    delete waitingIds[id];
    setMoodByCode(m);
    say(reply || '嗯……');
  };

  window.__daoUpdated = function (changed) {
    loadExtras();
    if (changed) say('我又学了点新东西，点「看知识」能瞧见。');
  };

  function showKnow() {
    if (!window.DaoNative) { say('知识库要在手机 App 里才看得到。'); return; }
    var d = {};
    try { d = JSON.parse(DaoNative.getKnowledge()); } catch (e) {}
    var cnt = d.count || 0, ln = d.lines || 0, today = d.today || '';
    var txt = '我已经学了 ' + cnt + ' 条，话也多了 ' + ln + ' 句。';
    if (today) txt += '今天学到：' + today;
    else txt += '今天还没学到新的，等会儿我再去看看。';
    say(txt);
    waveLeft = 1.4; mode = 'wave';
  }

  if (askBox) {
    document.getElementById('askSend').addEventListener('click', function () {
      var v = askInput.value.trim();
      if (!v) return;
      closeAsk(); askBrain(v, askMode);
    });
    askInput.addEventListener('keydown', function (e) {
      if (e.key === 'Enter') {
        var v = askInput.value.trim();
        if (!v) return;
        closeAsk(); askBrain(v, askMode);
      }
    });
  }

  document.getElementById('btnKnow').addEventListener('click', showKnow);

  var be = document.getElementById('btnExplain');
  if (be) be.addEventListener('click', function () { askSide('explain'); });

  // ---- 和电脑互通 / 查新版本 ----
  window.__daoMsg = function (id, status, msg) {
    say(msg || '好了');
    if (status === 'ok') { loadExtras(); waveLeft = 1.2; mode = 'wave'; }
    if (status === 'update') { waveLeft = 1.6; mode = 'wave'; }
  };

  var pcPanel = document.getElementById('pcPanel');

  document.getElementById('pcBtn').addEventListener('click', function (e) {
    e.stopPropagation();
    pcPanel.classList.toggle('show');
    document.getElementById('hint').textContent = pcPanel.classList.contains('show')
      ? '跟电脑连一下，记忆就能互相串' : '点一下它，它会有反应';
  });

  document.getElementById('pcSync').addEventListener('click', function () {
    pcPanel.classList.remove('show');
    if (!window.DaoNative || !DaoNative.syncNow) {
      say('记忆互通要跟电脑在同一个 WiFi；更新不用，点"查新版本"就行，换什么网都能查。');
      return;
    }
    say('我找找电脑在哪……');
    try { DaoNative.syncNow('s'); } catch (err) { say('叫不动同步。'); }
  });

  // 更新不靠 WiFi：换张网、换个地方，只要能上网就能拿到新版本
  var DL_PAGE = 'https://4mf81m04wehh3.doubao.link/app/app_17hnj8acgs2';

  document.getElementById('pcUpd').addEventListener('click', function () {
    pcPanel.classList.remove('show');
    say('我去网上看看有没有新版本。');
    setTimeout(function () {
      var w = null;
      try {
        if (window.DaoNative && DaoNative.openUrl) { DaoNative.openUrl(DL_PAGE); return; }
        w = window.open(DL_PAGE, '_blank');
      } catch (e) {}
      if (!w) { try { location.href = DL_PAGE; } catch (e2) {} }
    }, 700);
  });

  setTimeout(function () {
    loadExtras();
    if (window.DaoNative) {
      try { DaoNative.autoUpdate(); } catch (e) {}
      // 打开 App 时顺手跟电脑对一次话（找不到电脑就什么都不做）
      setTimeout(function () {
        try { if (DaoNative.syncNow) DaoNative.syncNow('auto'); } catch (e) {}
      }, 6000);
    }
  }, 1500);

  resize();
})();
